/**
 * Tipo di riga CSV: oggetti con il valore di ogni campo.
 * Il valore di ogni campo è un stringa (potente, anche se con virgolette o separatori).
 */
type CsvRow = Record<string, string>;

/**
 * Tipo generico per un array di righe CSV.
 */
type CsvData = CsvRow[];

/**
 * Gestisce il parsing di un testo CSV con caratteri di separazione
 * (default ',') e caratteri di isolamento per i campi contenenti virgolette.
 *
 * @param csvText - Il testo CSV da parseare.
 * @param separator - Il carattere di separazione tra i campi (default: ',').
 * @param quoteChar - Il carattere usato per isolare i campi contenenti virgolette (default: '"').
 * @returns Un array di righe CSV (CsvData).
 */
function parseCsv(
    csvText: string,
    separator: string = ",",
    quoteChar: string = '"'
): CsvData {
    const rows: CsvData = [];
    let currentRow: CsvRow = {};
    let currentField = "";
    let inQuotes = false;
    let fieldStarted = false;
    let fieldValue = "";
    let i = 0;

    while (i < csvText.length) {
        const char = csvText[i];

        // Gestisce la chiusura delle virgolette
        if (inQuotes && char === quoteChar) {
            inQuotes = false;
            fieldStarted = true;
        } else if (!inQuotes && char === quoteChar) {
            // Controlla se è la primissima virgolette di un nuovo campo
            if (!fieldStarted) {
                inQuotes = true;
                fieldStarted = true;
            }
        } else if (!inQuotes && char === separator) {
            // Separatore interno campo (senza virgolette)
            if (fieldStarted) {
                currentRow[fieldValue] = fieldValue;
                delete currentRow[fieldValue];
            }
            fieldStarted = false;
            fieldValue = "";
        } else if (!inQuotes && char === "\n") {
            // Fine di una riga: salva la riga precedente
            rows.push(currentRow);
            currentRow = {};
            currentField = "";
            fieldValue = "";
            fieldStarted = false;
        } else if (char === " ") {
            // Espansore per spazi (se richiesto, default non agisce)
            if (fieldStarted) {
                fieldValue += char;
                fieldStarted = true;
            }
        } else {
            // Carattere normale: aggiunge al campo corrente
            if (fieldStarted) {
                fieldValue += char;
            } else {
                fieldValue = char;
                fieldStarted = true;
            }
        }

        i++;
    }

    // Salva la ultima riga se esiste
    if (Object.keys(currentRow).length > 0 || fieldStarted) {
        rows.push(currentRow);
    }

    return rows;
}

